struct SecurityContext { const Principal* who; TenantId tenant; };

Decision guard_list_orders(const SecurityContext& ctx, const Request& req)
{
    if (ctx.who == nullptr) return Decision::Deny;  // absent == unauthenticated
    return policy().evaluate(*ctx.who, req);
}

