thread_local const SecurityContext* current = nullptr;

struct ScopedContext {                        // deterministic bind + restore
    const SecurityContext* prev;
    explicit ScopedContext(const SecurityContext& c)
        : prev(std::exchange(current, &c)) {}
    ~ScopedContext() { current = prev; }
};
